function HomePanel({ name, onNavigate, onEnroll, myCourses = [], allCourses = [], completedLessons = 0, certificates = [], workshops = [], registeredWorkshops = [] }) {
  const [activitySearchTerm, setActivitySearchTerm] = useState("");
  const [activityFilter, setActivityFilter] = useState("All");
  
  const enrolledCount = myCourses.length;
  const certificatesCount = certificates?.length || 0;
  // Show ALL registered workshops as "Upcoming/Enrolled" instead of ONLY completed/attended ones
  const registeredCount = registeredWorkshops?.length || 0;
  
  const filteredCourses = myCourses.filter(c => {
    const matchesSearch = (c.title || "").toLowerCase().includes(activitySearchTerm.toLowerCase()) ||
                          (c.instructor || "").toLowerCase().includes(activitySearchTerm.toLowerCase());
    const matchesFilter = activityFilter === "All" || 
                          (activityFilter === "In Progress" && (c.progress || 0) > 0 && (c.progress || 0) < 100) ||
                          (activityFilter === "Completed" && (c.progress || 0) === 100) ||
                          (activityFilter === "Not Started" && (c.progress || 0) === 0);
    return matchesSearch && matchesFilter;
  });

  const displayedCourses = filteredCourses.slice(0, 5); // Increased limit slightly for better discovery

  return (
    <>
      <section className="courses-progress-section">
        <div className="progress-card">
          <div className="std-recent-header">
            <div className="std-header-top">
              <h3>Recent Activity</h3>
              <button className="view-all" onClick={() => onNavigate('learn-discovery')}>View My Courses</button>
            </div>
            
            <div className="std-header-controls">
              <div className="panel-search std-activity-search">
                <i className="ri-search-line"></i>
                <input 
                  type="text" 
                  placeholder="Search your courses..." 
                  value={activitySearchTerm}
                  onChange={(e) => setActivitySearchTerm(e.target.value)}
                />
              </div>
              <div className="std-filter-group">
                {['All', 'In Progress', 'Completed', 'Not Started'].map(f => (
                  <button 
                    key={f} 
                    className={`std-filter-btn ${activityFilter === f ? 'active' : ''}`}
                    onClick={() => setActivityFilter(f)}
                  >
                    {f}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="std-table-wrap">
            <table className="std-table">
              <thead>
                <tr>
                  <th className="col-course">Course name</th>
                  <th className="col-cat">Category</th>
                  <th className="col-instr">Instructor</th>
                  <th className="col-prog">Progress</th>
                  <th className="col-lv">Level</th>
                  <th className="col-dur">Duration</th>
                  <th className="col-act">Action</th>
                </tr>
              </thead>
              <tbody>
                {displayedCourses.map(course => (
                  <tr key={course.id}>
                    <td className="col-course">
                      <div className="course-name-cell">
                        <span className="title-text">{course.title}</span>
                      </div>
                    </td>
                    <td className="col-cat"><span className="cat-label">{course.category || 'General'}</span></td>
                    <td className="col-instr"><span className="instr-name" title={parseInstructors(course.instructor).join(', ')}>{parseInstructors(course.instructor).join(', ')}</span></td>
                    <td className="col-prog">
                      <div className="progress-cell">
                        <div className="prog-bar"><div className="prog-fill" style={{ width: `${course.progress || 0}%` }}></div></div>
                        <span className="prog-percentage">{course.progress || 0}%</span>
                      </div>
                    </td>
                    <td className="col-lv"><span className={`badge ${(course.level || 'Beginner').toLowerCase()}`}>{course.level || 'Beginner'}</span></td>
                    <td className="col-dur"><span className="dur-text"><i className="ri-time-line"></i>{course.duration || 'Self-paced'}</span></td>
                    <td className="col-act">
                      <button className="row-action" title="Resume Learning" onClick={() => onNavigate('learn-player', course)}>
                         <i className="ri-play-circle-fill"></i>
                      </button>
                    </td>
                  </tr>
                ))}
                {filteredCourses.length === 0 && (
                  <tr>
                    <td className="col-course" style={{ padding: '60px 20px', textAlign: 'center', color: 'var(--text-soft)', flex: '1' }}>
                      <i className="ri-search-line" style={{ fontSize: '2rem', display: 'block', marginBottom: '1rem', opacity: 0.3 }}></i>
                      No courses found matching your criteria.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div id="tour-dashboard-stats" className="stats-sidebar">
          <div className="stat-box">
            <div className="stat-icon blue"><i className="ri-book-open-fill"></i></div>
            <div><strong>{enrolledCount} Courses</strong><span>Enrolled</span></div>
          </div>
          <div className="stat-box">
            <div className="stat-icon green"><i className="ri-clipboard-fill"></i></div>
            <div><strong>{completedLessons} Lessons</strong><span>Completed</span></div>
          </div>
          <div className="stat-box">
            <div className="stat-icon orange"><i className="ri-star-fill"></i></div>
            <div><strong>{certificatesCount} Certificates</strong><span>Earned</span></div>
          </div>
          <div className="stat-box">
            <div className="stat-icon red"><i className="ri-team-fill"></i></div>
            <div><strong>{registeredCount} Workshops</strong><span>Registered</span></div>
          </div>
        </div>
      </section>

      <section className="recommended-section">
        <div className="section-header">
          <h3>Recommended Courses</h3>
          <button className="view-all" onClick={() => onNavigate('learn-discovery')}>Browse All</button>
        </div>
        <div className="recommended-grid">
          {[...allCourses].sort((a, b) => {
            const dateA = a.created_at ? new Date(a.created_at) : new Date(0);
            const dateB = b.created_at ? new Date(b.created_at) : new Date(0);
            return dateB - dateA;
          }).slice(0, 3).map(course => {
            const isEnrolled = myCourses.some(mc => mc.id === course.id);
            return (
              <div key={course.id} className="rec-card">
                <div className="rec-thumb" style={{ backgroundImage: `url(${course.coverImage})`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
                  <span className="rec-price">Free</span>
                </div>
                <div className="rec-body">
                  <h4 className="truncate-1">{course.title || 'Untitled Course'}</h4>
                  <p className="truncate-2">{course.description?.[0] === '{' ? 'Course details...' : (course.description?.substring(0, 80) || 'Course details...') }…</p>
                  <div className="rec-meta">
                    <span className="badge">{course.level || 'Beginner'}</span>
                    <span className="badge">{course.duration || 'Self-paced'}</span>
                    <span className="badge">{course.lessons || 0} Lessons</span>
                  </div>
                  {isEnrolled ? (
                    <button className="special-button enroll-btn enrolled" onClick={() => onNavigate('learn-player', course)}>
                      <i className="ri-checkbox-circle-fill"></i> Enrolled
                    </button>
                  ) : (
                    <button className="special-button enroll-btn" onClick={() => onEnroll(course)}>
                      Enroll Now
                    </button>
                  )}
                </div>
              </div>
            );
          })}
          {myCourses.length === 0 && <div style={{gridColumn: '1/-1', textAlign: 'center', padding: '20px', color: 'var(--text-soft)'}}>Browse all courses to find your next lesson.</div>}
        </div>
      </section>
    </>
  );
}

/* ═══════════════════════════════════════════════════════════════
   PANEL: COURSES
   ═══════════════════════════════════════════════════════════════ */

function CoursesPanel({ onNavigate, myCourses = [] }) {
  const [filter, setFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [viewMode, setViewMode] = useState('grid');
  const itemsPerPage = viewMode === 'grid' ? 10 : 15;

  const filtered = (filter === 'all'
    ? (myCourses || [])
    : filter === 'completed'
      ? (myCourses || []).filter(c => (c.progress || 0) === 100)
      : filter === 'in-progress'
        ? (myCourses || []).filter(c => (c.progress || 0) > 0 && (c.progress || 0) < 100)
        : (myCourses || []).filter(c => (c.progress || 0) === 0)
  ).filter(c => 
    (c.title || "").toLowerCase().includes(searchTerm.toLowerCase()) ||
    (c.category || "").toLowerCase().includes(searchTerm.toLowerCase()) ||
    (c.instructor || "").toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const pagedItems = filtered.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handlePageChange = (page) => {
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <section className="std-panel">
      <div className="section-header">
        <div className="section-title-group">
          <h3>My Courses</h3>
          <div className="panel-search">
            <i className="ri-search-line"></i>
            <input 
              type="text" 
              placeholder="Filter courses..." 
              value={searchTerm}
              onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }}
            />
          </div>
        </div>
        <div className="std-filter-row">
          {[{id:'all',l:'All'},{id:'in-progress',l:'In Progress'},{id:'completed',l:'Completed'},{id:'not-started',l:'Not Started'}].map(f => (
            <button key={f.id} className={`std-filter-btn ${filter === f.id ? 'active' : ''}`} onClick={() => { setFilter(f.id); setCurrentPage(1); }}>{f.l}</button>
          ))}
          <div className="std-view-toggle">
            <button 
              className={`std-view-btn ${viewMode === 'grid' ? 'active' : ''}`} 
              onClick={() => setViewMode('grid')}
            >
              <i className="ri-grid-fill"></i>
            </button>
            <button 
              className={`std-view-btn ${viewMode === 'list' ? 'active' : ''}`} 
              onClick={() => setViewMode('list')}
            >
              <i className="ri-list-check"></i>
            </button>
          </div>
        </div>
      </div>

      {viewMode === 'grid' ? (
        <div className="std-course-grid">
          {pagedItems.map(course => (
            <div key={course.id} className="std-course-card" onClick={() => onNavigate('learn-player', course)}>
              <div className="std-course-thumb">
                <img 
                  src={course.coverImage} 
                  alt={course.title} 
                  className="std-course-cover-img" 
                  onError={(e) => {
                    e.target.onerror = null;
                    e.target.src = 'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&q=80&w=800';
                  }}
                />
                <span className={`badge ${course.level.toLowerCase()}`}>{course.level}</span>
              </div>
              <div className="std-course-info">
                <span className="std-course-cat">{course.category || 'General'}</span>
                <h4 className="truncate-1">{course.title || 'Untitled Course'}</h4>
                <p className="std-instructor"><i className="ri-user-line"></i> {parseInstructors(course.instructor).join(', ')}</p>
                <div className="std-progress-row">
                  <div className="prog-bar"><div className="prog-fill" style={{ width: `${course.progress || 0}%` }}></div></div>
                  <span className="std-progress-text">{course.progress || 0}%</span>
                </div>
                <div className="std-course-bottom">
                  <span><i className="ri-time-line"></i> {course.duration || 'Self-paced'}</span>
                  <span><i className="ri-book-open-line"></i> {course.lessons || 0} lessons</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="std-table-wrap">
          <table className="std-table">
            <thead>
                <tr>
                  <th className="col-course">Course name</th>
                  <th className="col-cat">Category</th>
                  <th className="col-instr">Instructor</th>
                  <th className="col-prog">Progress</th>
                  <th className="col-lv">Level</th>
                  <th className="col-dur">Duration</th>
                  <th className="col-act">Action</th>
                </tr>
            </thead>
            <tbody>
              {pagedItems.map(course => (
                  <tr key={course.id} onClick={() => onNavigate('learn-player', course)}>
                    <td className="col-course">
                      <div className="course-name-cell">
                         <span className="title-text">{course.title}</span>
                      </div>
                    </td>
                    <td className="col-cat">
                      <span className="cat-label">{course.category || 'General'}</span>
                    </td>
                    <td className="col-instr">
                      <span className="instr-name" title={parseInstructors(course.instructor).join(', ')}>{parseInstructors(course.instructor).join(', ')}</span>
                    </td>
                    <td className="col-prog">
                      <div className="progress-cell">
                        <div className="prog-bar"><div className="prog-fill" style={{ width: `${course.progress || 0}%` }}></div></div>
                        <span className="prog-percentage">{course.progress || 0}%</span>
                      </div>
                    </td>
                    <td className="col-lv"><span className={`badge ${(course.level || 'Beginner').toLowerCase()}`}>{course.level || 'Beginner'}</span></td>
                    <td className="col-dur">
                      <span className="dur-text"><i className="ri-time-line"></i> {course.duration || 'Self-paced'}</span>
                    </td>
                    <td className="col-act">
                      <button className="row-action" title="Resume Learning" onClick={(e) => { e.stopPropagation(); onNavigate('learn-player', course); }}>
                         <i className="ri-play-circle-fill"></i>
                      </button>
                    </td>
                  </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {filtered.length === 0 && <div style={{textAlign:'center', padding:'40px', color:'var(--text-soft)'}}>No courses found matching your criteria.</div>}
      <Pagination 
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={handlePageChange}
      />
    </section>
  );
}


/* ═══════════════════════════════════════════════════════════════
   MODAL: WORKSHOP REGISTRATION
   ═══════════════════════════════════════════════════════════════ */
function WorkshopRegistrationModal({ workshop, onClose, onConfirm }) {
  const [form, setForm] = useState({
    name: '',
    email: '',
    role: '',
    reason: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    onConfirm(form);
  };

  return (
    <div className="status-modal-overlay">
      <div className="status-modal-container animate-up" style={{ maxWidth: '550px' }}>
        <div className="status-modal-content">
          <div className="status-modal-header">
            <div className="status-modal-icon-wrap" style={{ backgroundColor: '#f0fdf4', color: '#16a34a' }}>
              <i className="ri-calendar-check-line"></i>
            </div>
            <div className="status-modal-text">
              <h3 className="status-modal-title">Workshop Registration</h3>
              <p className="status-modal-desc">Registering for: <strong>{workshop.title}</strong></p>
            </div>
          </div>

          <form id="registration-form" className="adm-form" style={{ marginTop: '20px' }} onSubmit={handleSubmit}>
            <div className="adm-form-grid">
              <div className="input-field">
                <label>Full Name</label>
                <input 
                  type="text" 
                  placeholder="John Doe" 
                  required 
                  value={form.name}
                  onChange={e => setForm({...form, name: e.target.value})}
                />
              </div>
              <div className="input-field">
                <label>Email Address</label>
                <input 
                  type="email" 
                  placeholder="john@example.com" 
                  required 
                  value={form.email}
                  onChange={e => setForm({...form, email: e.target.value})}
                />
              </div>
              <div className="input-field">
                <label>Professional Role</label>
                <input 
                  type="text" 
                  placeholder="Governance Officer, Student, etc." 
                  required 
                  value={form.role}
                  onChange={e => setForm({...form, role: e.target.value})}
                />
              </div>
              <div className="input-field">
                <label>Reason for Attending</label>
                <textarea 
                  placeholder="What do you hope to learn?" 
                  rows="3" 
                  required
                  style={{ 
                    width: '100%', 
                    padding: '12px', 
                    borderRadius: '8px', 
                    border: '1px solid var(--stroke-soft)', 
                    fontSize: '0.9rem', 
                    fontFamily: 'inherit',
                    resize: 'vertical',
                    outline: 'none',
                    transition: 'border-color 0.2s'
                  }}
                  value={form.reason}
                  onChange={e => setForm({...form, reason: e.target.value})}
                ></textarea>
              </div>
            </div>
          </form>
        </div>

        <div className="status-modal-footer">
          <button className="btn-outline" onClick={onClose}>Cancel</button>
          <button type="submit" form="registration-form" className="special-button">Confirm Registration</button>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   PANEL: WORKSHOP
   ═══════════════════════════════════════════════════════════════ */
function WorkshopPanel({ onRegister, registeredIds = [], workshops = [] }) {
  const [tab, setTab] = useState('upcoming');
  const [searchTerm, setSearchTerm] = useState("");

  const filtered = workshops.filter(p => {
    const status = (p.status || "").toLowerCase();
    const matchesTab = tab === 'upcoming' ? status === 'upcoming' : status === 'completed';
    const matchesSearch = p.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          (p.host || "").toLowerCase().includes(searchTerm.toLowerCase());
    return matchesTab && matchesSearch;
  });

  return (
    <section className="std-panel">
      <div className="section-header">
        <div className="section-title-group">
          <h3>Workshops</h3>
          <div className="panel-search">
            <i className="ri-search-line"></i>
            <input 
              type="text" 
              placeholder="Filter workshops..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="std-filter-row">
          <button className={`std-filter-btn ${tab === 'upcoming' ? 'active' : ''}`} onClick={() => setTab('upcoming')}>Upcoming</button>
          <button className={`std-filter-btn ${tab === 'completed' ? 'active' : ''}`} onClick={() => setTab('completed')}>Completed</button>
        </div>
      </div>
      <div className="std-workshop-list">
        {filtered.map((w, index) => {
          const isRegistered = registeredIds.includes(w.id);
          return (
            <div key={w.id} className={`std-workshop-card ${isRegistered ? 'registered' : ''}`} style={isRegistered ? { borderColor: '#fbbf24', borderWidth: '2px' } : {}}>
              <div className="std-ws-date" style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center' }}>
                <span className="std-ws-month" style={{ fontSize: '0.75rem', opacity: 0.8, letterSpacing: '1px' }}>WS</span>
                <span className="std-ws-day" style={{ fontSize: '1.6rem', fontWeight: 'bold', lineHeight: 1 }}>{index + 1}</span>
              </div>
              <div className="std-ws-info">
                <h4>{w.title}</h4>
                <div className="std-ws-meta">
                  <span><i className="ri-time-line"></i> {w.time}</span>
                  <span><i className="ri-user-line"></i> {w.host}</span>
                  <span><i className="ri-team-line"></i> {w.attendees} attendees</span>
                </div>
                <div className="std-ws-tags">
                  <span className={`badge ${(w.status || "").toLowerCase() === 'upcoming' ? 'beginner' : ''}`}>{w.format}</span>
                  <span className={`badge ${(w.status || "").toLowerCase() === 'upcoming' ? 'advance' : 'medium'}`}>{w.status}</span>
                </div>
              </div>
              <div className="std-ws-action">
                {(w.status || "").toLowerCase() === 'upcoming' ? (
                  isRegistered ? (
                    <span className="badge" style={{ backgroundColor: '#fef3c7', color: '#92400e', padding: '0.6rem 1.2rem', borderRadius: '12px', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <i className="ri-checkbox-circle-fill"></i> Registered
                    </span>
                  ) : (
                    <button 
                      className="special-button" 
                      style={{fontSize: '0.8rem', padding: '0.5rem 1rem'}}
                      onClick={() => onRegister(w)}
                    >
                      Register
                    </button>
                  )
                ) : (
                  <button className="btn-outline" style={{fontSize: '0.8rem', padding: '0.5rem 1rem'}}>View Replay</button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

