const StudentDashboard = ({ user, onNavigate, onLogout, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState(() => {
    return localStorage.getItem('studentActiveTab') || "Home";
  });

  const { activeTour, currentStep, startTour, hasCompletedTour, triggerFeatureAnnouncement } = useTour();

  // Onboarding first login auto-trigger
  useEffect(() => {
    if (!hasCompletedTour('platform') && !activeTour) {
      const timer = setTimeout(() => {
        startTour('platform');
      }, 1500); // 1.5s delay to allow dashboard to mount nicely
      return () => clearTimeout(timer);
    }
  }, [hasCompletedTour, activeTour]);

  // Sync activeTab with active tour step
  useEffect(() => {
    if (activeTour === 'platform') {
      const stepTabs = [
        'Home',          // Step 0: Welcome Centered
        'Home',          // Step 1: Stats Highlight
        'Courses',       // Step 2: Courses Panel
        'Research',      // Step 3: Research Panel
        'Workshop',      // Step 4: Workshop Panel
        'Resources',     // Step 5: Resources Panel
        'Certifications',// Step 6: Certifications Panel
        'Settings',      // Step 7: Settings Panel
        'Home'           // Step 8: Completion Centered
      ];
      const targetTab = stepTabs[currentStep];
      if (targetTab && targetTab !== activeTab) {
        setActiveTab(targetTab);
      }
    }
  }, [activeTour, currentStep]);

  // Unified "What's New" Feature Announcement auto-trigger
  useEffect(() => {
    // Only show if main onboarding is completed, and they haven't seen this notice
    const platformCompleted = localStorage.getItem('grh_onboarding_complete');
    const noticeSeen = localStorage.getItem('grh_whatsnew_seen_research_gaps');
    if (platformCompleted && !noticeSeen) {
      const timer = setTimeout(() => {
        triggerFeatureAnnouncement(
          'research_gaps',
          '#tour-sidebar-Research',
          'New: AI Research Assistant 🔮',
           "We've supercharged the Research Sandbox! You can now analyse complex documents and literature with natural language queries powered by GovAI-Core."
        );
      }, 3500); // Trigger a bit after dashboard load
      return () => clearTimeout(timer);
    }
  }, [triggerFeatureAnnouncement]);

  // Imagery Hooks for Resources with document-centric focus
  const { getImage: getPerlImg } = usePixabayImages('finance', 10, null, true);
  const { getImage: getSparcImg } = usePixabayImages('sparc', 10, null, true);
  const { getImage: getGovImg } = usePixabayImages('governance', 10, null, true);
  const { getImage: getLibImg } = usePixabayImages('library', 6, null, true);

  useEffect(() => {
    localStorage.setItem('studentActiveTab', activeTab);
  }, [activeTab]);

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [profileName, setProfileName] = useState(user?.name || user?.email?.split('@')[0] || "Alex");
  const [profileAvatar, setProfileAvatar] = useState(user?.avatar_url || null);
  const [stats, setStats] = useState({ courses: 0, lessons: 0, certifications: 0 });

  // Keep local profile state in sync with global user prop
  useEffect(() => {
    if (user) {
      if (user.name) setProfileName(user.name);
      if (user.avatar_url) setProfileAvatar(user.avatar_url);
    }
  }, [user]);

  // Status & Registration Modal States
  const [statusModal, setStatusModal] = useState({ 
    isOpen: false, 
    type: 'warning', 
    title: '', 
    message: '', 
    onConfirm: null 
  });
  const [regModal, setRegModal] = useState({ isOpen: false, workshop: null });
  const [registeredWorkshops, setRegisteredWorkshops] = useState([]);
  const [myCourses, setMyCourses] = useState([]);
  const [allCourses, setAllCourses] = useState([]);
  const [workshops, setWorkshops] = useState([]);
  const [certificates, setCertificates] = useState([]);
  const [allResources, setAllResources] = useState([]);
  const [rawResources, setRawResources] = useState([]);
  const [completedLessons, setCompletedLessons] = useState(0);
  const [loading, setLoading] = useState(true);

  // Certificate Preview State
  const [certPreview, setCertPreview] = useState({ 
    isOpen: false, 
    certificate: null 
  });

  const fetchData = async () => {
    if (!user) {
      setLoading(false);
      return;
    }
    
    // Safety timeout to prevent stuck loading screens
    const safetyTimer = setTimeout(() => {
      setLoading(false);
    }, 5000);

    try {
      setLoading(true);
      
      // 1. Fetch all raw data first
      // SAFE FETCHING logic: ensure individual table errors don't crash everything
      const results = await Promise.allSettled([
        supabase.from('profiles').select('*').eq('id', user.id).single(),
        supabase.from('courses').select('*'),
        supabase.from('workshops').select('*'),
        supabase.from('workshop_registrations').select('workshop_id').eq('user_id', user.id),
        supabase.from('user_progress').select('*').eq('user_id', user.id),
        supabase.from('course_modules').select('id, course_id'),
        supabase.from('library_resources').select('*').eq('status', 'Published'),
        supabase.from('books').select('*').eq('status', 'Published'),
        supabase.from('sparc_resources').select('*'),
        supabase.from('perl_resource').select('*')
      ]);

      const [
        profileRes,
        coursesRes,
        workshopsRes,
        regsRes,
        progressRes,
        modulesRes,
        libRes,
        booksRes,
        sparcRes,
        perlRes
      ] = results;

      const profile          = profileRes.status === 'fulfilled' ? profileRes.value.data : null;
      const coursesData      = coursesRes.status === 'fulfilled' ? coursesRes.value.data : [];
      const workshopsData    = workshopsRes.status === 'fulfilled' ? workshopsRes.value.data : [];
      const regsData         = regsRes.status    === 'fulfilled' ? regsRes.value.data : [];
      const userProgress     = progressRes.status === 'fulfilled' ? progressRes.value.data : [];
      const allModules       = modulesRes.status  === 'fulfilled' ? modulesRes.value.data : [];
      const library_resources = libRes.status      === 'fulfilled' ? libRes.value : { data: [] };
      const books            = booksRes.status    === 'fulfilled' ? booksRes.value : { data: [] };
      const sparc_resources  = sparcRes.status    === 'fulfilled' ? sparcRes.value : { data: [] };
      const perl_resource    = perlRes.status     === 'fulfilled' ? perlRes.value : { data: [] };

      // 2. Sync profile
      if (profile) {
        setProfileName(profile.name || user.email?.split('@')[0]);
        setProfileAvatar(profile.avatar_url);
      }

      // 3. Process mappings
      const courseModuleCounts = (allModules || []).reduce((acc, m) => {
        acc[m.course_id] = (acc[m.course_id] || 0) + 1;
        return acc;
      }, {});

      const userCompletedModulesPerCourse = (userProgress || []).filter(p => p.completed).reduce((acc, p) => {
        acc[p.course_id] = (acc[p.course_id] || 0) + 1;
        return acc;
      }, {});

      // 4. Calculate progress and completions
      const getSafeImg = (c, i) => {
        const val = c.thumbnail || c.cover_image || c.coverImage || "";
        if (val && val.length > 10) return val;
        return `${COURSE_IMAGE_BANK[i % COURSE_IMAGE_BANK.length]}?auto=format&fit=crop&w=600&q=80`;
      };

      const completedCount = (userProgress || []).filter(p => p.completed).length;
      setCompletedLessons(completedCount);

      const coursesWithProgress = (coursesData || []).map((c, i) => {
        const total = courseModuleCounts[c.id] || 0;
        const completed = userCompletedModulesPerCourse[c.id] || 0;
        return {
          ...c,
          coverImage: getSafeImg(c, i),
          progress: total > 0 ? Math.round((completed / total) * 100) : 0
        };
      });

      const earnedCertificates = (coursesData || []).filter(course => {
        const total = courseModuleCounts[course.id] || 0;
        const completed = userCompletedModulesPerCourse[course.id] || 0;
        return total > 0 && completed >= total;
      }).map(course => ({
        id: course.id,
        title: course.title,
        issueDate: new Date().toLocaleDateString('en-US', { month: 'short', year: 'numeric' }),
        credentialId: `GRH-${course.id.toString().substring(0, 8).toUpperCase()}`,
        grade: 'A',
        status: 'Earned'
      }));

      // 5. Update states
      if (regsData) {
        setRegisteredWorkshops(regsData.map(r => r.workshop_id));
      }
      setCertificates(earnedCertificates);
      setAllCourses(coursesWithProgress);
      
      const enrolled = coursesWithProgress.filter(c => {
        const hasProgress = c.progress > 0;
        const existsInProgress = (userProgress || []).some(p => p.course_id === c.id);
        return hasProgress || existsInProgress;
      });
      setMyCourses(enrolled);
      setWorkshops(workshopsData || []);

      // 6. Process Resources (Normalization)
      const DEFAULT_RES_IMG = 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=400&q=80';
      const normalizedResources = [
        ...(library_resources.data || []).map(r => ({
          ...r,
          type: r.type || 'PERL',
          author: r.author || 'GRH',
          year: r.published_year || (r.created_at ? new Date(r.created_at).getFullYear() : new Date().getFullYear()),
          coverImage: DEFAULT_RES_IMG
        })),
        ...(books.data || []).map(b => ({
          ...b,
          type: 'Book',
          author: b.author || 'GRH Hub',
          year: b.published_year || (b.created_at ? new Date(b.created_at).getFullYear() : new Date().getFullYear()),
          coverImage: b.image_url || 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=400&q=80',
          file_url: b.file_url || ''
        })),
        ...(sparc_resources.data || []).map(s => ({
          ...s,
          type: 'SPARC',
          author: s.author || 'SPARC',
          year: s.created_at ? new Date(s.created_at).getFullYear() : new Date().getFullYear(),
          coverImage: DEFAULT_RES_IMG,
          file_url: s.preview_url || s.download_url
        })),
        ...(perl_resource.data || []).map(p => ({
          ...p,
          type: 'PERL',
          author: p.author || 'PERL',
          year: p.created_at ? new Date(p.created_at).getFullYear() : new Date().getFullYear(),
          coverImage: DEFAULT_RES_IMG,
          file_url: p.preview_url || p.download_url
        }))
      ];
      setRawResources(normalizedResources);

    } catch (err) {
      console.error("Error fetching dashboard data:", err);
    } finally {
      clearTimeout(safetyTimer);
      setLoading(false);
    }
  };

  // REACTIVE IMAGERY ENGINE: Identical to the Library logic
  useEffect(() => {
    if (rawResources.length === 0) return;
    
    const DEFAULT_IMG = 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=400&q=80';
    
    const enriched = rawResources.map((item, idx) => {
      let coverImage = item.coverImage;
      
      if (!coverImage || coverImage === DEFAULT_IMG) {
        if (item.type === 'Book') {
          coverImage = item.image_url || getLibImg(idx) || "https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=400&q=80";
        } else if (item.type === 'SPARC') {
          coverImage = getSparcImg(idx) || DEFAULT_IMG;
        } else if (item.type === 'PERL') {
          coverImage = getPerlImg(idx) || DEFAULT_IMG;
        } else {
          coverImage = getGovImg(idx) || DEFAULT_IMG;
        }
      }
      
      return { ...item, coverImage };
    });
    
    setAllResources(enriched);
  }, [rawResources, getPerlImg, getSparcImg, getGovImg, getLibImg]);

  const handleCertDownload = (cert) => {
    generateCertificatePDF({
      recipientName: profileName,
      courseTitle: cert.title,
      date: cert.issueDate,
      certificateId: cert.credentialId
    }, true);
  };

  const handleCertShare = async (cert) => {
    const text = `I just earned my certification in ${cert.title} from Governance Resource Hub! Credential ID: ${cert.credentialId}`;
    const url = window.location.origin;
    
    if (navigator.share) {
      try {
        await navigator.share({
          title: `Governance Certificate: ${cert.title}`,
          text,
          url
        });
      } catch (err) {
        console.log('Share failed or cancelled', err);
      }
    } else {
      navigator.clipboard.writeText(`${text} ${url}`);
      setStatusModal({
        isOpen: true,
        type: 'success',
        title: 'Share link copied',
        message: 'The certificate information and link have been copied to your clipboard.',
        onConfirm: () => setStatusModal(prev => ({ ...prev, isOpen: false }))
      });
    }
  };

  const handleCertPreview = (cert) => {
    setCertPreview({ isOpen: true, certificate: cert });
  };

  useEffect(() => {
    fetchData();

    // Subscribe to real-time changes
    const coursesChannel = supabase
      .channel('student-dashboard:courses')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'courses' }, () => {
        fetchData();
      })
      .subscribe();

    const workshopsChannel = supabase
      .channel('student-dashboard:workshops')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'workshops' }, () => {
        fetchData();
      })
      .subscribe();

    const resourcesChannel = supabase
      .channel('student-dashboard:library-resources')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'library_resources' }, () => {
        fetchData();
      })
      .subscribe();

    const booksChannel = supabase
      .channel('student-dashboard:books')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'books' }, () => {
        fetchData();
      })
      .subscribe();

    const progressChannel = supabase
      .channel('student-dashboard:user_progress')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'user_progress', filter: `user_id=eq.${user.id}` }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(coursesChannel);
      supabase.removeChannel(workshopsChannel);
      supabase.removeChannel(resourcesChannel);
      supabase.removeChannel(booksChannel);
      supabase.removeChannel(progressChannel);
    };
  }, [user]);

  const handleEnroll = async (course) => {
    if (!user) return;
    try {
      setLoading(true);
      
      // 1. Fetch first module
      const { data: modules } = await supabase
        .from('course_modules')
        .select('id')
        .eq('course_id', course.id)
        .order('sort_order', { ascending: true })
        .limit(1);

      if (!modules || modules.length === 0) {
        setStatusModal({
          isOpen: true,
          type: 'warning',
          title: 'Coming Soon',
          message: 'This course is currently being prepared and has no modules yet. Please check back later!',
          onConfirm: () => setStatusModal(prev => ({ ...prev, isOpen: false }))
        });
        return;
      }

      // 2. Insert into user_progress (upsert to be safe)
      const { error } = await supabase
        .from('user_progress')
        .upsert({
          user_id: user.id,
          course_id: course.id,
          module_id: modules[0].id,
          completed: false,
          status: 'in-progress'
        }, { onConflict: 'user_id,module_id' });

      if (error) throw error;

      // 3. Show Success Modal
      setStatusModal({
        isOpen: true,
        type: 'success',
        title: 'Enrollment Successful!',
        message: `You have successfully enrolled in "${course.title}". You can now start learning from your dashboard!`,
        onConfirm: () => {
          setStatusModal(prev => ({ ...prev, isOpen: false }));
          fetchData(); 
        }
      });

    } catch (err) {
      console.error("Enrollment error:", err);
      setStatusModal({
        isOpen: true,
        type: 'error',
        title: 'Enrollment Failed',
        message: err.message || 'An error occurred during enrollment. Please try again.',
        onConfirm: () => setStatusModal(prev => ({ ...prev, isOpen: false }))
      });
    } finally {
      setLoading(false);
    }
  };

  const confirmLogout = () => {
    setStatusModal({
      isOpen: true,
      type: 'warning',
      title: 'Sign Out',
      message: 'Are you sure you want to log out of your student account?',
      onConfirm: () => {
        setStatusModal(prev => ({ ...prev, isOpen: false }));
        onLogout();
      }
    });
  };

  const handleRegistration = (workshop) => {
    setRegModal({ isOpen: true, workshop });
  };

  const submitRegistration = async (formData) => {
    if (!user) return;
    try {
      const workshopId = regModal.workshop?.id;
      const { error } = await supabase.from('workshop_registrations').insert([{
        workshop_id: workshopId,
        user_id: user.id,
        name: formData.name,
        email: formData.email,
        role: formData.role,
        reason: formData.reason
      }]);

      if (error) throw error;

      setRegModal({ isOpen: false, workshop: null });
      setRegisteredWorkshops(prev => [...prev, workshopId]);

      setStatusModal({
        isOpen: true,
        type: 'success',
        title: 'Registration Successful',
        message: `You have successfully registered for "${regModal.workshop?.title}". We've sent the details to your email.`,
        onConfirm: () => setStatusModal(prev => ({ ...prev, isOpen: false }))
      });
    } catch (err) {
      if (err.message?.includes('duplicate key value')) {
        setRegModal({ isOpen: false, workshop: null });
        setRegisteredWorkshops(prev => [...prev, regModal.workshop?.id]);
        setStatusModal({ isOpen: true, type: 'success', title: 'Already Registered', message: 'You are already registered for this workshop.', onConfirm: () => setStatusModal(p => ({ ...p, isOpen: false })) });
      } else {
        setStatusModal({ isOpen: true, type: 'error', title: 'Registration Failed', message: 'Registration failed: ' + err.message, onConfirm: () => setStatusModal(p => ({ ...p, isOpen: false })) });
      }
    }
  };

  const renderPanel = () => {
    if (loading) return <div className="std-panel" style={{display:'flex', alignItems:'center', justifyContent:'center', minHeight:'400px'}}>Loading dashboard...</div>;

    switch (activeTab) {
      case 'Home':           return <HomePanel name={profileName} onNavigate={onNavigate} onEnroll={handleEnroll} myCourses={myCourses} allCourses={allCourses} completedLessons={completedLessons} certificates={certificates} workshops={workshops} registeredWorkshops={registeredWorkshops} />;
      case 'Courses':        return <CoursesPanel onNavigate={onNavigate} myCourses={myCourses} />;
      case 'Research':       return <ResearchPanel user={user} />;
      case 'Workshop':       return <WorkshopPanel onRegister={handleRegistration} registeredIds={registeredWorkshops} workshops={workshops} />;
      case 'Resources':      return <ResourcesPanel resources={allResources} onNavigate={onNavigate} />;
      case 'Certifications': return (
        <CertificationsPanel 
          certificates={certificates} 
          allCoursesCount={myCourses.length}
          onPreview={handleCertPreview}
          onDownload={handleCertDownload}
          onShare={handleCertShare}
        />
      );
      case 'Settings':       return <SettingsPanel user={user} profileName={profileName} setProfileName={setProfileName} profileAvatar={profileAvatar} setProfileAvatar={setProfileAvatar} fetchData={fetchData} setStatusModal={setStatusModal} />;
      default:               return <HomePanel name={profileName} onNavigate={onNavigate} onEnroll={handleEnroll} myCourses={myCourses} allCourses={allCourses} completedLessons={completedLessons} certificates={certificates} workshops={workshops} registeredWorkshops={registeredWorkshops} />;
    }
  };

  return (
    <>
      {/* Mobile sidebar toggle button */}
      <button
        className="sidebar-mobile-toggle"
        onClick={() => setSidebarOpen(!sidebarOpen)}
        aria-label="Toggle sidebar"
      >
        <i className={sidebarOpen ? 'ri-close-line' : 'ri-menu-line'}></i>
      </button>

      <div className="student-dashboard-wrapper">
        {/* Backdrop for mobile */}
        {sidebarOpen && (
          <div className="sidebar-backdrop" onClick={() => setSidebarOpen(false)} />
        )}

        {/* ===== SIDEBAR ===== */}
        <aside className={`student-sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
          <div className="sidebar-logo" onClick={() => onNavigate('welcome')} style={{ cursor: 'pointer' }}>
            <img src={mainLogo} alt="Governance Resource Hub" />
          </div>

          <nav className="sidebar-nav">
            {NAV_GROUPS.map(group => (
              <React.Fragment key={group.label}>
                <span className="sidebar-section-label">{group.label}</span>
                {group.links.map(link => (
                  <button
                    key={link.name}
                    id={`tour-sidebar-${link.name}`}
                    className={`sidebar-link ${activeTab === link.name ? 'active' : ''}`}
                    onClick={() => { setActiveTab(link.name); setSidebarOpen(false); }}
                  >
                    <i className={link.icon}></i>
                    {link.name}
                    {link.badge && <span className="link-badge">{link.badge}</span>}
                    {link.name === 'Research' && !localStorage.getItem('grh_whatsnew_seen_research_gaps') && (
                      <span className="whats-new-pulsar" />
                    )}
                  </button>
                ))}
              </React.Fragment>
            ))}
          </nav>

          <div className="sidebar-footer">
            <span className="sidebar-section-label">Account</span>
            <button id="tour-sidebar-Settings" className={`sidebar-link ${activeTab === 'Settings' ? 'active' : ''}`} onClick={() => setActiveTab('Settings')}>
              <i className="ri-settings-fill"></i> Settings
            </button>
            <button className="sidebar-link" onClick={() => startTour('platform')}>
              <i className="ri-compass-3-fill"></i> Tour Guide
            </button>
            <button className="sidebar-link"><i className="ri-question-fill"></i> Help Center</button>
            <button className="sidebar-link student-exit-portal" onClick={() => onNavigate('welcome')}>
              <i className="ri-arrow-left-line"></i> Back to Site
            </button>
            <button className="sidebar-link student-logout" onClick={confirmLogout}>
              <i className="ri-logout-box-line"></i> Sign Out
            </button>
          </div>
        </aside>

        {/* ===== MAIN ===== */}
        <main className="student-main">
          {/* Topbar */}
          <header className="student-topbar">
            <div className="topbar-welcome">
              <span role="img" aria-label="wave" className="desktop-only">👋</span>
              <div>
                <h3>Welcome back, {profileName}!</h3>
                <p className="desktop-only">Continue your governance learning journey.</p>
              </div>
            </div>
            {/* Remove global search from centre as it's now local to panels */}
            <div className="topbar-spacer" style={{ flex: 1 }}></div>
            <div className="topbar-actions">
              <button className="action-btn"><i className="ri-notification-fill"></i></button>
              <div className="user-profile">
                {profileAvatar ? (
                  <img src={profileAvatar} alt="Avatar" className="user-avatar" style={{ objectFit: 'cover' }} />
                ) : (
                  <div className="user-avatar">{profileName[0]?.toUpperCase() || 'A'}</div>
                )}
                <div className="user-info">
                  <strong>{profileName}</strong>
                  <span>Governance Learner</span>
                </div>
              </div>
            </div>
          </header>

          {/* ===== SCROLLABLE CONTENT AREA ===== */}
          <div className="content-area">
            {renderPanel()}
          </div>
        </main>
      </div>

      {statusModal.isOpen && (
        <StatusModal
          isOpen={statusModal.isOpen}
          onClose={() => setStatusModal(prev => ({ ...prev, isOpen: false }))}
          onCancel={() => setStatusModal(prev => ({ ...prev, isOpen: false }))}
          type={statusModal.type}
          title={statusModal.title}
          message={statusModal.message}
          confirmLabel={statusModal.type === 'success' ? 'Great!' : 'Yes, Proceed'}
          onConfirm={statusModal.onConfirm}
        />
      )}

      {regModal.isOpen && (
        <WorkshopRegistrationModal 
          workshop={regModal.workshop} 
          onClose={() => setRegModal({ isOpen: false, workshop: null })}
          onConfirm={submitRegistration}
        />
      )}
      
      {/* Certificate Preview Modal */}
      <CertificatePreview 
        isOpen={certPreview.isOpen}
        onClose={() => setCertPreview({ isOpen: false, certificate: null })}
        recipientName={profileName}
        courseTitle={certPreview.certificate?.title}
        date={certPreview.certificate?.issueDate}
        certificateId={certPreview.certificate?.credentialId}
        downloadAction={() => handleCertDownload(certPreview.certificate)}
      />

      {/* Dynamic Context-Driven Onboarding Tour Overlay */}
      <TourGuideRenderer />
    </>
  );
};

export default StudentDashboard;
